# Pester unit tests for the Dependency License Checker.
#
# TDD approach: each Describe block below was written test-first (red), then the
# corresponding function in ../DependencyLicenseChecker.ps1 was implemented to make
# it pass (green), then refactored. The script is dot-sourced so its functions are
# available here; a guard in the script prevents its "main" body from executing on
# dot-source.

BeforeAll {
    . "$PSScriptRoot/../DependencyLicenseChecker.ps1"
}

Describe 'Get-LicenseStatus' {
    It 'returns approved when the license is on the allow-list' {
        Get-LicenseStatus -License 'MIT' -AllowList @('MIT', 'ISC') -DenyList @('GPL-3.0') |
            Should -Be 'approved'
    }
}

